class Solution {public:vector<vector<int>> solve(GraphNode* graph){if(!graph)return {};unordered_map<GraphNode*,int>id;vector<GraphNode*>q{graph};id[graph]=0;for(int i=0;i<(int)q.size();i++)for(auto v:q[i]->neighbors)if(!id.count(v)){id[v]=q.size();q.push_back(v);}vector<vector<int>>out(q.size(),vector<int>(q.size()));for(int i=0;i<(int)q.size();i++)for(auto v:q[i]->neighbors)out[i][id[v]]++;return out;}};